console.log('[md-insert-video] Script loaded'); document.addEventListener('DOMContentLoaded', function () { console.log('[md-insert-video] DOM ready'); let videoModal = null; let videoListContainer = document.getElementById('videoList'); let uploadForm = document.getElementById('uploadVideoForm'); let uploadBtn = document.getElementById('uploadVideoBtn'); let uploadStatus = document.getElementById('uploadVideoStatus'); let videoUrlInput = document.getElementById('videoUrlInput'); let insertUrlVideoBtn = document.getElementById('insertUrlVideoBtn'); let selectedTextarea = null; function initModal() { if (!videoModal && document.getElementById('insertVideoModal')) { console.log('[md-insert-video] Initializing modal'); videoModal = new bootstrap.Modal(document.getElementById('insertVideoModal')); } } function getCurrentCSRFToken() { let metaTag = document.querySelector('meta[name="csrf_token"]'); return metaTag ? metaTag.getAttribute('content') : ''; } document.addEventListener('md-mini:insert-video', function (e) { console.log('[md-insert-video] Insert video event triggered'); initModal(); selectedTextarea = e.detail.textarea; console.log('[md-insert-video] Textarea:', selectedTextarea ? 'found' : 'not found'); if (videoModal) { loadVideos(); videoModal.show(); } else { console.error('[md-insert-video] Modal not initialized'); } }); function loadVideos() { console.log('[md-insert-video] Loading videos'); if (!videoListContainer) { console.error('[md-insert-video] videoListContainer not found'); return } fetch('/api/videos', { method: 'GET', headers: { 'Content-Type': 'application/json' } }).then(r => { console.log('[md-insert-video] Response status:', r.status); if (r.status === 401) { console.log('[md-insert-video] Not authenticated'); videoListContainer.innerHTML = '<div class="alert alert-info mb-0">Faça login para usar este recurso</div>'; return [] } return r.json(); }).then(videos => { console.log('[md-insert-video] Loaded', videos ? videos.length : 0, 'videos'); if (!videos || videos.length === 0) { videoListContainer.innerHTML = '<div class="text-center text-body-secondary py-4"><small>Nenhum vídeo disponível. Faça upload de um novo.</small></div>'; return } let html = ''; videos.forEach(video => { html += '<div class="mb-3 p-2" style="border-bottom: 1px solid var(--bs-border-color);">'; html += '<div class="mb-2"><strong>' + escapeHtml(video.display_name) + '</strong></div>'; html += '<video style="max-width: 100%; width: 100%; height: auto; background-color: #000; border-radius: 0.375rem; margin-bottom: 0.5rem;" controls><source src="' + escapeHtml(video.file_url) + '"></video>'; if (video.description) { html += '<div class="small text-body-secondary mb-2">' + escapeHtml(video.description) + '</div>'; } html += '<div class="d-flex gap-2">'; html += '<button type="button" class="btn btn-sm btn-outline-primary select-video-btn" data-url="' + escapeHtml(video.file_url) + '" data-name="' + escapeHtml(video.display_name) + '">Inserir</button>'; html += '<small class="text-body-secondary align-self-center">' + escapeHtml(video.created_at || '') + '</small>'; html += '</div>'; html += '</div>'; }); videoListContainer.innerHTML = html; document.querySelectorAll('.select-video-btn').forEach(btn => { btn.addEventListener('click', function () { insertVideo(this.getAttribute('data-url'), this.getAttribute('data-name')); }); }); }).catch(err => { console.error('[md-insert-video] Error loading videos:', err); videoListContainer.innerHTML = '<div class="alert alert-danger mb-0">Erro ao carregar vídeos: ' + err + '</div>'; }); } if (uploadForm) { uploadForm.addEventListener('submit', function (e) { e.preventDefault(); let file = document.getElementById('videoFileInput').files[0]; if (!file) { uploadStatus.innerHTML = '<div class="alert alert-warning mb-0">Selecione um vídeo</div>'; return } console.log('[md-insert-video] Uploading video:', file.name); uploadStatus.innerHTML = '<div class="alert alert-info mb-0">Enviando...</div>'; uploadBtn.disabled = true; let formData = new FormData(); formData.append('file', file); formData.append('original_filename', file.name); formData.append('description', document.getElementById('videoDescription').value || file.name); formData.append('filetag', 'forum'); formData.append('csrf_token', getCurrentCSRFToken()); fetch('/files/upload', { method: 'POST', body: formData }).then(r => r.text()).then(html => { console.log('[md-insert-video] Upload response received, length:', html.length); if (html.indexOf('alert-danger') !== -1 || html.indexOf('error') !== -1 || html.indexOf('Error') !== -1) { console.error('[md-insert-video] Upload error in response'); uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload. Verifique o tamanho do arquivo (máx. 500 MB).</div>'; } else { console.log('[md-insert-video] Upload successful'); uploadStatus.innerHTML = '<div class="alert alert-success mb-0">Upload concluído. Recarregando lista...</div>'; document.getElementById('videoFileInput').value = ''; document.getElementById('videoDescription').value = ''; setTimeout(function () { loadVideos(); uploadStatus.innerHTML = ''; }, 1500); } }).catch(err => { console.error('[md-insert-video] Upload error:', err); uploadStatus.innerHTML = '<div class="alert alert-danger mb-0">Erro ao fazer upload: ' + err + '</div>'; }).finally(() => { uploadBtn.disabled = false; }); }); } if (insertUrlVideoBtn) { insertUrlVideoBtn.addEventListener('click', function () { let url = videoUrlInput.value.trim(); if (!url) { console.warn('[md-insert-video] Empty URL'); return } insertVideo(url, 'Vídeo'); }); } function insertVideo(url, name) { console.log('[md-insert-video] Inserting video:', url); if (!selectedTextarea) { console.error('[md-insert-video] No textarea selected'); return } let markdown = '<video style="max-width: 100%; width: 100%; height: auto;" controls><source src="' + url + '" type="video/mp4"></video>'; selectedTextarea.value += '\n' + markdown; selectedTextarea.dispatchEvent(new Event('change', { bubbles: true })); console.log('[md-insert-video] Video markdown inserted'); if (videoModal) videoModal.hide(); } function escapeHtml(text) { if (!text) return ''; let map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }; return text.replace(/[&<>"']/g, m => map[m]); } });
